import re
from pathlib import Path
from statistics import mean

text = Path('results_eval.md').read_text(encoding='utf-8')
lines_all = text.splitlines()
lines = [ln for ln in lines_all if ln.strip().startswith('|')]

header1_line = lines[0]
header2_line = next(ln for ln in lines if 'Issue id' in ln)

header1 = [c.strip() for c in header1_line.strip().split('|')[1:-1]]
header2 = [c.strip() for c in header2_line.strip().split('|')[1:-1]]

col_info = []
current_method = None
for i, (h1, h2) in enumerate(zip(header1, header2)):
    h2_clean = re.sub(r'<br>', ' ', h2)
    if h1 and not re.fullmatch(r'Col\\d+', h1):
        current_method = h1
    if i <= 5:
        method = None
    else:
        method = current_method
    col_info.append((method, h2_clean))

methods = ['ROAM', 'PRM-Enumeration', 'Euler']
match_cols = {m: None for m in methods}
for idx, (method, metric) in enumerate(col_info):
    if method in methods and 'Match' in metric and 'Accuracy' in metric:
        match_cols[method] = idx

start_idx = lines.index(header2_line) + 1
values = {m: [] for m in methods}

for row_line in lines[start_idx:]:
    row_line = row_line.strip()
    if not row_line or set(row_line) == {'|'}:
        continue
    cells = [c.strip() for c in row_line.split('|')[1:-1]]
    if len(cells) != len(header1):
        continue
    for method, col_idx in match_cols.items():
        if col_idx is None:
            continue
        raw = cells[col_idx]
        if not raw:
            continue
        try:
            v = float(raw)
        except ValueError:
            continue
        values[method].append(v)

stats = {}
for m in methods:
    vs = values[m]
    avg_pct = round(mean(vs) * 100)
    perfect_pct = round(100 * sum(1 for v in vs if abs(v - 1.0) < 1e-9) / len(vs))
    zero_pct = round(100 * sum(1 for v in vs if abs(v) < 1e-9) / len(vs))
    stats[m] = (avg_pct, perfect_pct, zero_pct)

prm_avg, prm_perf, prm_zero = stats['PRM-Enumeration']
euler_avg, euler_perf, euler_zero = stats['Euler']
roam_avg, roam_perf, roam_zero = stats['ROAM']

out = Path('/workspace/repro.txt')
out.write_text(f"""**Table 2: The Match Accuracy Results on Bug Reports (Shown as a Percent)**\n\n|                 | Match Accuracy | Perfect Cases   | Zero Cases  |\n| --------------- | :------------: | :-----------:   | :--------:  |\n| PRM-Enumeration |       {prm_avg}       |       {prm_perf}      |     {prm_zero}     |\n| Euler           |       {euler_avg}       |       {euler_perf}      |     {euler_zero}     |\n| Roam            |       {roam_avg}       |       {roam_perf}      |      {roam_zero}     |\n""", encoding='utf-8')

print(out.read_text(encoding='utf-8'))
